const msg = $input.first().json.messages[0];
const msgType = msg.type;
let textBody = '';
let interactiveId = null;
let interactiveTitle = null;
let isInteractive = false;

if (msgType === 'interactive') {
  isInteractive = true;
  if (msg.interactive && msg.interactive.list_reply) {
    interactiveId = msg.interactive.list_reply.id;
    interactiveTitle = msg.interactive.list_reply.title;
    textBody = msg.interactive.list_reply.title;
  } else if (msg.interactive && msg.interactive.button_reply) {
    interactiveId = msg.interactive.button_reply.id;
    interactiveTitle = msg.interactive.button_reply.title;
    textBody = msg.interactive.button_reply.title;
  } else {
    textBody = 'Unknown interactive response';
  }
} else if (msgType === 'text') {
  textBody = msg.text.body;
} else {
  textBody = '';
}

return [{
  json: {
    ...($input.first().json),
    _parsed: {
      textBody,
      interactiveId,
      interactiveTitle,
      isInteractive,
      msgType,
      from: msg.from
    }
  }
}];

const responseText = $input.first().json.text || '';
try {
  const cleaned = responseText.replace(/```json?/gi, '').replace(/```/g, '').trim();
  const parsed = JSON.parse(cleaned);
  return [{ json: { intent: parsed.intent || 'general_inquiry' } }];
} catch (e) {
  const text = responseText.toLowerCase();
  if (text.includes('book_appointment')) return [{ json: { intent: 'book_appointment' } }];
  if (text.includes('cancel_appointment')) return [{ json: { intent: 'cancel_appointment' } }];
  if (text.includes('reschedule_appointment')) return [{ json: { intent: 'reschedule_appointment' } }];
  if (text.includes('check_appointment')) return [{ json: { intent: 'check_appointment' } }];
  return [{ json: { intent: 'general_inquiry' } }];
}

const phone = $node['WhatsApp Trigger1'].json.messages[0].from;
const responseText = $node['Extract Booking Details'].json.text || '{}';
// Strip markdown fences if model adds them
const cleaned = responseText.replace(/```json?/gi, '').replace(/```/g, '').trim();
let rawExtract = {};
try { rawExtract = JSON.parse(cleaned); } catch (e) { rawExtract = {}; }

// Check if this was an interactive response and override extracted fields
const parsed = $node['Parse Interactive Response'].json._parsed || {};
if (parsed.isInteractive && parsed.interactiveId) {
  const id = parsed.interactiveId;
  const serviceMap = {
    'svc_gel_manicure': 'Gel Manicure Deluxe',
    'svc_luxury_pedicure': 'Luxury Pedicure',
    'svc_gel_extensions': 'Full Gel Nail Extensions',
    'svc_botox': 'Botox Aesthetic Session',
    'svc_lip_filler': 'Lip Dermal Filler Session'
  };
  if (serviceMap[id]) {
    rawExtract.serviceName = serviceMap[id];
  }
  if (id.startsWith('slot_')) {
    const timeParts = id.replace('slot_', '').split('_');
    if (timeParts.length === 2) {
      rawExtract.preferredTime = `${timeParts[0]}:${timeParts[1]}`;
    }
  }
}

// Read existing session from the Fetch Session HTTP response
const fetchResponse = $input.first().json;
const existingSession = (fetchResponse && fetchResponse.data) ? fetchResponse.data : null;

// Build session: start with defaults, layer existing DB session, then newly extracted data
const session = {
  fullName: null,
  phoneNumber: phone,
  serviceName: null,
  preferredDate: null,
  preferredTime: null,
  paymentMethod: 'cash',
  paymentStatus: 'pending',
  notes: null
};

// Merge existing session from Supabase
if (existingSession) {
  if (existingSession.full_name) session.fullName = existingSession.full_name;
  if (existingSession.service_name) session.serviceName = existingSession.service_name;
  if (existingSession.preferred_date) session.preferredDate = existingSession.preferred_date;
  if (existingSession.preferred_time) session.preferredTime = existingSession.preferred_time;
  if (existingSession.payment_method) session.paymentMethod = existingSession.payment_method;
  if (existingSession.payment_status) session.paymentStatus = existingSession.payment_status;
  if (existingSession.notes) session.notes = existingSession.notes;
}

// Merge newly extracted variables (overrides existing if not null)
if (rawExtract.fullName) session.fullName = rawExtract.fullName;
if (rawExtract.serviceName) session.serviceName = rawExtract.serviceName;
if (rawExtract.preferredDate) session.preferredDate = rawExtract.preferredDate;
if (rawExtract.preferredTime) session.preferredTime = rawExtract.preferredTime;
if (rawExtract.paymentMethod) session.paymentMethod = rawExtract.paymentMethod;
if (rawExtract.paymentStatus) session.paymentStatus = rawExtract.paymentStatus;
if (rawExtract.notes) session.notes = rawExtract.notes;

return [{ json: { session, phone } }];

const { session, phone } = $input.first().json;

let missingField = null;
let promptMessage = '';

if (!session.serviceName) {
  missingField = 'serviceName';
  promptMessage = 'Please select a treatment from the list below to start your booking at Lumière Med Spa! 🌸';
} else if (!session.preferredDate) {
  missingField = 'preferredDate';
  promptMessage = `Got it! A *${session.serviceName}*. 📅\n\nPlease type your preferred date using the format *YYYY-MM-DD* (e.g. *2026-05-28*):`;
} else if (!session.preferredTime) {
  missingField = 'preferredTime';
  promptMessage = `Checking available time slots for ${session.serviceName} on ${session.preferredDate}...`;
} else if (!session.fullName) {
  missingField = 'fullName';
  promptMessage = `Almost done! 🌸\n\nCould you please reply with your *Full Name* to complete the registration?`;
}

const isComplete = !missingField;

return [{ json: { isComplete, missingField, promptMessage, session, phone } }];

