const phone = $node['Collect User Details Node'].json.phone;
const session = $node['Collect User Details Node'].json.session;
const apiResponse = $input.first().json;

// Extract available slots from backend response
let slots = [];
if (apiResponse.slots && Array.isArray(apiResponse.slots)) {
  slots = apiResponse.slots;
} else if (apiResponse.data && Array.isArray(apiResponse.data)) {
  slots = apiResponse.data;
} else if (Array.isArray(apiResponse)) {
  slots = apiResponse;
}

// If no slots from API, generate default working-hour slots
if (slots.length === 0) {
  slots = ['09:00', '09:30', '10:00', '10:30', '11:00', '11:30', '12:00', '13:00', '13:30', '14:00', '14:30', '15:00', '15:30', '16:00', '16:30', '17:00', '17:30', '18:00', '18:30'];
}

// WhatsApp interactive list max 10 rows
const limitedSlots = slots.slice(0, 10);

function formatTime(slot) {
  const timeStr = typeof slot === 'string' ? slot : (slot.time || slot.startTime || slot.slot || '');
  if (!timeStr) return { raw: '09:00', display: '9:00 AM' };
  const parts = timeStr.split(':');
  const h = parseInt(parts[0]);
  const m = parts[1] || '00';
  const ampm = h >= 12 ? 'PM' : 'AM';
  const h12 = h > 12 ? h - 12 : (h === 0 ? 12 : h);
  return { raw: `${parts[0]}:${m}`, display: `${h12}:${m} ${ampm}` };
}

const rows = limitedSlots.map(slot => {
  const t = formatTime(slot);
  const rawParts = t.raw.split(':');
  return {
    id: `slot_${rawParts[0]}_${rawParts[1]}`,
    title: t.display,
    description: `${session.serviceName} on ${session.preferredDate}`
  };
});

const interactivePayload = {
  messaging_product: 'whatsapp',
  recipient_type: 'individual',
  to: phone,
  type: 'interactive',
  interactive: {
    type: 'list',
    header: { type: 'text', text: '🕒 Available Time Slots' },
    body: { text: `Here are the available time slots for ${session.serviceName} on ${session.preferredDate}. Tap to select your preferred time! 🌸` },
    footer: { text: 'Lumière Med Spa · Mon-Sat 9AM-7PM, Sun 10AM-5PM' },
    action: {
      button: 'View Time Slots',
      sections: [{ title: '⏰ Available Times', rows: rows }]
    }
  }
};

return [{ json: { payload: interactivePayload, phone, session } }];

