const suggestionsList = suggestions && suggestions.length > 0 
  ? suggestions.map(time => `• ${time}`).join('
')
  : 'Please pick another time.';
const text = `⚠️ I'm sorry, that slot is already booked.

Would you prefer any of these 3 alternative times instead?
${suggestionsList}

Simply type the preferred time to complete your booking! 🌸`;
