const phone = $node['WhatsApp Trigger1'].json.messages[0].from;
const intent = $node['Parse Intent Response'].json.intent;

const appointments = $input.first().json.data || [];
const cleanPhone = (p) => p ? p.replace(/\D/g, '') : '';
const targetApp = appointments.find(app => cleanPhone(app.phone_number) === cleanPhone(phone));

return [{
  json: {
    phone,
    intent,
    appointmentFound: !!targetApp,
    appointmentId: targetApp ? targetApp.id : null,
    serviceName: targetApp ? targetApp.service_name : '',
    appointmentDate: targetApp ? targetApp.appointment_date : '',
    appointmentTime: targetApp ? targetApp.appointment_time : ''
  }
}];

